document:
query MenuDetails($id: ID!) {
  menu(id: $id) {
    ...MenuDetails
  }
}

fragment MenuDetails on Menu {
  id
  items {
    ...MenuItemNested
  }
  name
}

fragment MenuItemNested on MenuItem {
  ...MenuItem
  children {
    ...MenuItem
    children {
      ...MenuItem
      children {
        ...MenuItem
        children {
          ...MenuItem
          children {
            ...MenuItem
            children {
              ...MenuItem
            }
          }
        }
      }
    }
  }
}

fragment MenuItem on MenuItem {
  category {
    id
    name
  }
  collection {
    id
    name
  }
  id
  level
  name
  page {
    id
    title
  }
  url
}
